(120075, 'ruRU', 'Мана... Мне нужна... мана...', '', 25549),
(120074, 'ruRU', 'Звуковой эффект для войск', 'Звуковой эффект для войск', 25549),
(120073, 'ruRU', 'Умоляю... Я голодаю много недель...', '', 25549),
(120072, 'ruRU', 'Звуковой эффект для войск', '', 25549),
(120071, 'ruRU', 'Звуковой эффект для войск', 'Звуковой эффект для войск', 25549),
