UPDATE `broadcast_text_locale` SET `MaleText_lang`='Аллена Брайта можно найти на тренировочной площадке у казармы.\n\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.', `FemaleText_lang`='Аллена Брайта можно найти на тренировочной площадке у казармы.\n\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.', `VerifiedBuild`=25549 WHERE (`ID`=52053 AND `locale`='ruRU');
