UPDATE `broadcast_text_locale` SET `MaleText_lang`='Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе... кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в "Приюте фокусника" к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.', `FemaleText_lang`='Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе... кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в "Приюте фокусника" к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.', `VerifiedBuild`=25549 WHERE (`ID`=48051 AND `locale`='ruRU');
