UPDATE `broadcast_text_locale` SET `MaleText_lang`='Если этот с виду неуклюжий олух смог захватить меня, то ты воистину храбрец, раз $gрешил:решила; прийти мне на помощь. \n\nМой дар к твоим услугам – если, конечно, тебе удастся отвлечь Халфия и освободить меня от этих цепей.\n\nВ моих силах заключить врага в водоворот неистовой бури, что не позволит ему обрушить на тебя Кольцо Тьмы.', `VerifiedBuild`=25549 WHERE (`ID`=46116 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Если этот с виду неуклюжий олух смог захватить меня, то ты воистину храбрец, раз $gрешил:решила; прийти мне на помощь. \n\nМой дар к твоим услугам – если, конечно, тебе удастся отвлечь Халфия и освободить меня от этих цепей.\n\nВ моих силах временно парализовать врага, чтобы ты $gсмог:смогла; противостоять его смертоносным ударам.', `VerifiedBuild`=25549 WHERE (`ID`=46115 AND `locale`='ruRU');
