UPDATE `broadcast_text_locale` SET `MaleText_lang`='Я действую от имени Вол''джина, и мне необходимо попасть на Колючий холм. Могу я одолжить нетопыря?', `FemaleText_lang`='Я действую от имени Вол''джина, и мне необходимо попасть на Колючий холм. Могу я одолжить нетопыря?', `VerifiedBuild`=25549 WHERE (`ID`=40435 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40434 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40433 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Что?! Что ты $gсказал:сказала;?! Да как ты $gпосмел:посмела;! Да ни одно пойло, которым потчуют на Хмельном фестивале, не может сравниться с моим пивом!\n\nТы заплатишь за свои слова, |3-6($c)!', `VerifiedBuild`=25549 WHERE (`ID`=40432 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40431 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='А ты $gсмелый парнишка:смелая девчушка;, раз $gотважился:отважилась; прийти сюда без приглашения.\n\nТак что тебе надо?', `VerifiedBuild`=25549 WHERE (`ID`=40430 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40429 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Кто-то должен остановить Королевскую химическую компанию. Готов поставить свою позолоченную ракету Пустоты, что под маркой бешеных шоколадок для населения они варят в своих лабораториях новую чуму...\n\nМне бы только найти смельчака, который передаст этим аптекарям повестку в суд! Тогда мы могли бы положить конец их деятельности... а заодно захватить все их активы!', `VerifiedBuild`=25549 WHERE (`ID`=40428 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40427 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='...Помоги... Пожалуйста...\n\n...Всадника без головы... Необходимо остановить...\n\n...Столько жертв! И до сих пор, стоит луне лишь появиться на небосклоне, как он вновь рыщет в поисках свежей крови...', `VerifiedBuild`=25549 WHERE (`ID`=40426 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40425 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Повелитель Холода Ахун должен быть остановлен.\n\nСейчас он еще обретает форму, освобожденный из тюрьмы стихий безумными сектантами Сумеречного Молота.\n\nЕсли мы не сможем предотвратить его появление в нашем мире, земля окажется под покровом бесконечной суровой зимы.', `VerifiedBuild`=25549 WHERE (`ID`=40424 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=40422 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Говорю тебе, этот Корен Худовар – чокнутый.\n\nЯ же не виноват в том, что его не пригласили на Хмельной фестиваль! Но ему и его дружкам из Черного Железа все равно – отделали моих трудяг да и выпили все пиво.\n\nКто-то должен положить этому конец!', `VerifiedBuild`=25549 WHERE (`ID`=40421 AND `locale`='ruRU');
