UPDATE `broadcast_text_locale` SET `MaleText_lang`='А когда кончится пиво,\nВ Тенегорн ломанемся,\nИ выпьем за Рагнароса...\n... а сам он, ха-ха, обойдется!', `FemaleText_lang`='А когда кончится пиво,\nВ Тенегорн ломанемся,\nИ выпьем за Рагнароса...\n... а сам он, ха-ха, обойдется!', `VerifiedBuild`=25549 WHERE (`ID`=22445 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Мы пьем с утра до вечера\nИз кружек и из бочек!\nБез пива жизнь нам не мила,\nА с пивом – даже очень!', `FemaleText_lang`='Мы пьем с утра до вечера\nИз кружек и из бочек!\nБез пива жизнь нам не мила,\nА с пивом – даже очень!', `VerifiedBuild`=25549 WHERE (`ID`=22444 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='И выпьем мы за Корена,\nЗа Харли, как всегда!\nХоть пойло выдохлось давно,\nНо все же не вода!', `FemaleText_lang`='И выпьем мы за Корена,\nЗа Харли, как всегда!\nХоть пойло выдохлось давно,\nНо все же не вода!', `VerifiedBuild`=25549 WHERE (`ID`=22443 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='"Вот портер пенится игриво,\nНо не видать вам наше пиво!\nВзамен мы стащим бочки ваши,\nА вы – хлебайте простоквашу!', `FemaleText_lang`='"Вот портер пенится игриво,\nНо не видать вам наше пиво!\nВзамен мы стащим бочки ваши,\nА вы – хлебайте простоквашу!', `VerifiedBuild`=25549 WHERE (`ID`=22442 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='"Мы – дворфы Черного Железа,\nС большой горы недавно слезли.\nГора та Черною зовется,\nВ ее пещерах пиво льется.', `FemaleText_lang`='"Мы – дворфы Черного Железа,\nС большой горы недавно слезли.\nГора та Черною зовется,\nВ ее пещерах пиво льется.', `VerifiedBuild`=25549 WHERE (`ID`=22441 AND `locale`='ruRU');
