UPDATE `broadcast_text_locale` SET `MaleText_lang`='Приветствую! Перед тобой – один из лучших музыкальных инструментов во всем Лордероне. Исполнять музыкальные произведения для хозяина и всех его гостей – большая честь для нас. Занимай место в зале: я слышу, представление скоро начнется.', `VerifiedBuild`=25549 WHERE (`ID`=18424 AND `locale`='ruRU');
