UPDATE `broadcast_text_locale` SET `MaleText_lang`='Я могу как-то помочь?', `FemaleText_lang`='Я могу как-то помочь?', `VerifiedBuild`=25549 WHERE (`ID`=18420 AND `locale`='ruRU');
