UPDATE `broadcast_text_locale` SET `MaleText_lang`='Отсюда, из вестибюля, ты можешь отправиться по одному из трех направлений. Ступени за моей спиной ведут в бальный зал, где сейчас развлекают гостей. Я уверен, ты чувствуешь запах стойл, а вход в комнаты слуг лежит недалеко от двери вестибюля.', `VerifiedBuild`=25549 WHERE (`ID`=18416 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Все вопросы, касающиеся Медива, лучше задавать Мороузу, дворецкому. Я сам слишком мало знаю о делах хозяина. Если хочешь узнать больше... думаю, у Мороуза в пиршественном зале сейчас находится несколько дворян.', `VerifiedBuild`=25549 WHERE (`ID`=18415 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Это башня Каражана и резиденция моего господина, Медива. Как скромный привратник я мало что могу объяснить.', `VerifiedBuild`=25549 WHERE (`ID`=18414 AND `locale`='ruRU');
