UPDATE `broadcast_text_locale` SET `MaleText_lang`='Большой дом в Колючем холме, но не казармы. Там поговори с трактирщиком Гроском. Ясно?', `FemaleText_lang`='Большой дом в Колючем холме, но не казармы. Там поговори с трактирщиком Гроском. Ясно?', `VerifiedBuild`=25549 WHERE (`ID`=6601 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Да, мне бы тоже не помешало отдохнуть и пропустить стаканчик... Таверна у нас в северо-западной части Колючего холма. Передавай привет трактирщику Гроску!', `FemaleText_lang`='Да, мне бы тоже не помешало отдохнуть и пропустить стаканчик... Таверна у нас в северо-западной части Колючего холма. Передавай привет трактирщику Гроску!', `VerifiedBuild`=25549 WHERE (`ID`=6600 AND `locale`='ruRU');
