UPDATE `broadcast_text_locale` SET `MaleText_lang`='Тебе нужно в Оргриммар. Иди от Колючего холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.', `FemaleText_lang`='Тебе нужно в Оргриммар. Иди от Колючего холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.', `VerifiedBuild`=25549 WHERE (`ID`=6593 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=6592 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Учитель снятия шкур есть в Оргриммаре. Чтобы попасть туда, иди на север по дороге из Колючего холма. Там спроси оргриммарских рубак – они знают.', `FemaleText_lang`='Учитель снятия шкур есть в Оргриммаре. Чтобы попасть туда, иди на север по дороге из Колючего холма. Там спроси оргриммарских рубак – они знают.', `VerifiedBuild`=25549 WHERE (`ID`=6591 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Говорят, Дуротар богат полезными ископаемыми... Разумеется, у нас в Колючем холме есть учитель горного дела. Ты можешь найти Крунна у кузницы в северо-западной части города.', `FemaleText_lang`='Говорят, Дуротар богат полезными ископаемыми... Разумеется, у нас в Колючем холме есть учитель горного дела. Ты можешь найти Крунна у кузницы в северо-западной части города.', `VerifiedBuild`=25549 WHERE (`ID`=6590 AND `locale`='ruRU');
