UPDATE `broadcast_text_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=6588 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Тебе нужно в Оргриммар. Иди от Колючего холма по северной дороге. Пройдешь через каньон – и попадешь прямо туда. Если что, спроси любого рубаку.', `FemaleText_lang`='Тебе нужно в Оргриммар. Иди от Колючего холма по северной дороге. Пройдешь через каньон – и попадешь прямо туда. Если что, спроси любого рубаку.', `VerifiedBuild`=25549 WHERE (`ID`=6587 AND `locale`='ruRU');
