UPDATE `broadcast_text_locale` SET `MaleText_lang`='Со всеми этими боями, что мы ведем, у нас, конечно же, есть учитель первой помощи на Колючем холме. Ищи Роурка в казармах в восточной части города.', `FemaleText_lang`='Со всеми этими боями, что мы ведем, у нас, конечно же, есть учитель первой помощи на Колючем холме. Ищи Роурка в казармах в восточной части города.', `VerifiedBuild`=25549 WHERE (`ID`=6581 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Один из них живет в казармах в восточной части Колючего холма. Звать его Роурк.', `FemaleText_lang`='Один из них живет в казармах в восточной части Колючего холма. Звать его Роурк.', `VerifiedBuild`=25549 WHERE (`ID`=6580 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ха, да это работа для гоблинов! Впрочем, у нас на Колючем холме есть один орк, который занимается такими вещами. Ищи Мукдрака возле кузницы.', `FemaleText_lang`='Ха, да это работа для гоблинов! Впрочем, у нас на Колючем холме есть один орк, который занимается такими вещами. Ищи Мукдрака возле кузницы.', `VerifiedBuild`=25549 WHERE (`ID`=6579 AND `locale`='ruRU');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='На Колючем холме есть учитель инженерного дела. Его зовут Мукдрак. Обычно его можно встретить возле кузни.', `FemaleText_lang`='На Колючем холме есть учитель инженерного дела. Его зовут Мукдрак. Обычно его можно встретить возле кузни.', `VerifiedBuild`=25549 WHERE (`ID`=6578 AND `locale`='ruRU');
