UPDATE `broadcast_text_locale` SET `MaleText_lang`='"Навык для тех, кто хочет преодолевать препятствия". Думаю, именно так Фоллиса описывает свои умения. \n\nЕсли тебе это нравится, отправляйся в Анклав Кенария в северной части Дарнаса – там она ведет занятия.', `FemaleText_lang`='"Навык для тех, кто хочет преодолевать препятствия". Думаю, именно так Фоллиса описывает свои умения. \n\nЕсли тебе это нравится, отправляйся в Анклав Кенария в северной части Дарнаса – там она ведет занятия.', `VerifiedBuild`=25549 WHERE (`ID`=5375 AND `locale`='ruRU');
