UPDATE `broadcast_text_locale` SET `MaleText_lang`='Горячий привет тебе, |3-6($c), от меня и от всего клана Изувеченной Длани.$B$BНу-ну, не удивляйся, $n. Даже среди самых высокопоставленных лиц Оргриммара есть те, в чьих душах скрывается тень. И даже добросердечный Тралл осознает необходимость клана Изувеченной Длани для общего блага орков и троллей.$B$BНо если ты здесь не для того, чтобы поговорить о моих делах, то зачем ты $gпришел:пришла;?', `VerifiedBuild`=25549 WHERE (`ID`=5182 AND `locale`='ruRU');
