UPDATE `broadcast_text_locale` SET `MaleText_lang`='Браэнна Кремнескал поистине творит чудеса. По всем жреческим делам надо обращаться именно к ней. \n\nИди на север от Врат Стальгорна к Залу Тайн. Там ты ее и найдешь.', `FemaleText_lang`='Браэнна Кремнескал поистине творит чудеса. По всем жреческим делам надо обращаться именно к ней. \n\nИди на север от Врат Стальгорна к Залу Тайн. Там ты ее и найдешь.', `VerifiedBuild`=25549 WHERE (`ID`=5101 AND `locale`='ruRU');
