UPDATE `broadcast_text_locale` SET `MaleText_lang`='Думаю, Бинк – наша крошка-чаровница из Зала Тайн – помогла бы тебе справиться с любым магическим делом.\n\nЗал Таинств находится к северу от Врат Стальгорна.', `FemaleText_lang`='Думаю, Бинк – наша крошка-чаровница из Зала Тайн – помогла бы тебе справиться с любым магическим делом.\n\nЗал Таинств находится к северу от Врат Стальгорна.', `VerifiedBuild`=25549 WHERE (`ID`=5098 AND `locale`='ruRU');
