UPDATE `broadcast_text_locale` SET `MaleText_lang`='Имей в виду, сейчас у меня нет времени на твои шуточки. Я слежу за тем, чтобы исследования верховного друида проходили по плану. Мне приказано избавляться от любых посторонних, если только они не хотят присоединиться к моему славному Кругу Кенария.', `VerifiedBuild`=25549 WHERE (`ID`=4659 AND `locale`='ruRU');
