UPDATE `broadcast_text_locale` SET `MaleText_lang`='Выбора у меня не было – по крайней мере, я так думал. Я должен был оставаться с королем и народом несмотря на падение Тауриссана.$B$BПодчиняясь Рагнаросу, король Дагран Тауриссан вырвал сердце горы и воздвиг пик Черной горы. Мы же неустанно трудились, возводя город, по своей мощи превосходящий все крепости прошлого... и будущего.', `VerifiedBuild`=25549 WHERE (`ID`=4649 AND `locale`='ruRU');
