UPDATE `broadcast_text_locale` SET `MaleText_lang`='В "Тканях Дункана" работает один из лучших портных Штормграда – Джорджио Болеро. Обязательно посетите этот магазин в Квартале Магов!', `FemaleText_lang`='В "Тканях Дункана" работает один из лучших портных Штормграда – Джорджио Болеро. Обязательно посетите этот магазин в Квартале Магов!', `VerifiedBuild`=25549 WHERE (`ID`=2963 AND `locale`='ruRU');
