UPDATE `broadcast_text_locale` SET `MaleText_lang`='Если хочешь научиться отлично готовить, отправляйся в таверну "Свинья и свисток" в старом городе и поговори со Стивеном Райбеком. Уж он-то умеет приготовить такие ребрышки, как никто другой.\n\nЭх... даже слюнки потекли из-за тебя. Но не рассчитывай, что он тебя и это блюдо выучит готовить!', `FemaleText_lang`='Если хочешь научиться отлично готовить, отправляйся в таверну "Свинья и свисток" в старом городе и поговори со Стивеном Райбеком. Уж он-то умеет приготовить такие ребрышки, как никто другой.\n\nЭх... даже слюнки потекли из-за тебя. Но не рассчитывай, что он тебя и это блюдо выучит готовить!', `VerifiedBuild`=25549 WHERE (`ID`=2955 AND `locale`='ruRU');
